Method.Source:
public str getName()
{
    return fieldPName(InventDim, InventColorId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    EcoResColor color;
    while select Name from color
        group by Name
    {
        if (!ret.in(color.Name))
        {
            ret.add(color.Name);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventColorId));
    qbr.value(queryValue(_value));
}
